<?php
namespace App\Http\Controllers;
use Illuminate\Http\Request;
use Illuminate\Support\Facades\DB;
use App\Models\{Product,Review};
use App\Services\GoldMarketService;
use App\Services\JewelryRecommender;
class FeatureController extends Controller {
 public function hub(GoldMarketService $market){ $products=Product::where('is_active',true)->latest()->take(8)->get();$categories=\App\Models\Category::orderBy('id')->get(['id','name']);$marketData=$market->dashboard();$rate=DB::table('gold_rates')->latest('effective_at')->first();if(!$rate){$rate=(object)['price_per_gram'=>(int)($marketData['gold18_toman']??0),'labor_percent'=>12,'profit_percent'=>8,'tax_percent'=>10];}return view('features.hub',compact('products','rate','marketData','categories')); }
 public function saveDesign(Request $r){$d=$r->validate(['design_type'=>'required|in:ring,necklace,bracelet,earring','configuration'=>'required|array','estimated_price'=>'required|integer|min:0']);$id=DB::table('custom_designs')->insertGetId(['user_id'=>$r->user()->id,'design_type'=>$d['design_type'],'configuration'=>json_encode($d['configuration'],JSON_UNESCAPED_UNICODE),'estimated_price'=>$d['estimated_price'],'status'=>'draft','created_at'=>now(),'updated_at'=>now()]);return response()->json(['ok'=>true,'design_id'=>$id,'message'=>'طرح ذخیره شد؛ قیمت نهایی پس از بررسی کارشناس مشخص می‌شود.']);}
 public function customOrder(Request $r){$d=$r->validate(['title'=>'required|string|max:120','brief'=>'required|string|max:5000']);DB::table('custom_orders')->insert(['user_id'=>$r->user()->id,'title'=>$d['title'],'brief'=>$d['brief'],'status'=>'submitted','created_at'=>now(),'updated_at'=>now()]);return back()->with('success','درخواست ساخت سفارشی ثبت شد.');}
 public function wishlist(Request $r,Product $product){$q=DB::table('wishlists')->where('user_id',$r->user()->id)->where('product_id',$product->id);if($q->exists()){$q->delete();$saved=false;}else{DB::table('wishlists')->insert(['user_id'=>$r->user()->id,'product_id'=>$product->id,'created_at'=>now(),'updated_at'=>now()]);$saved=true;}return back()->with('success',$saved?'به علاقه‌مندی‌ها اضافه شد.':'از علاقه‌مندی‌ها حذف شد.');}
 public function wishlistIndex(Request $r){$products=Product::with('category:id,name,slug')->whereIn('id',DB::table('wishlists')->where('user_id',$r->user()->id)->pluck('product_id'))->where('is_active',true)->get();return view('features.wishlist',compact('products'));}
 public function alert(Request $r,Product $product){$d=$r->validate(['target_price'=>'required|integer|min:1']);DB::table('price_alerts')->updateOrInsert(['user_id'=>$r->user()->id,'product_id'=>$product->id],['target_price'=>$d['target_price'],'is_active'=>true,'updated_at'=>now(),'created_at'=>now()]);return back()->with('success','هشدار قیمت ثبت شد.');}
 public function compare(Request $r,Product $product){$key=$r->session()->getId();DB::table('product_comparisons')->updateOrInsert(['session_key'=>$key,'product_id'=>$product->id],['user_id'=>$r->user()?->id,'updated_at'=>now(),'created_at'=>now()]);return back()->with('success','به مقایسه اضافه شد.');}
 public function compareIndex(Request $r){$key=$r->session()->getId();$products=Product::with('category')->whereIn('id',DB::table('product_comparisons')->where('session_key',$key)->pluck('product_id'))->where('is_active',true)->get();return view('features.compare',compact('products'));}
 public function compareRemove(Request $r,Product $product){DB::table('product_comparisons')->where('session_key',$r->session()->getId())->where('product_id',$product->id)->delete();return back()->with('success','محصول از مقایسه حذف شد.');}
 public function review(Request $r,Product $product){$d=$r->validate(['rating'=>'required|integer|min:1|max:5','body'=>'nullable|string|max:1500']);Review::updateOrCreate(['product_id'=>$product->id,'user_id'=>$r->user()->id],$d+['is_approved'=>false]);return back()->with('success','نظر شما ثبت شد و پس از بررسی نمایش داده می‌شود.');}
 public function recommendations(Request $r, JewelryRecommender $engine){$seed=$r->filled('product')?Product::whereKey($r->integer('product'))->first():null;$limit=(int)min(12,max(1,$r->integer('limit',8)));$categoryId=$r->integer('category') ?: null;$items=$engine->recommend($r,$seed,$categoryId?48:$limit);if($categoryId){$items=array_slice(array_values(array_filter($items,fn($i)=>(int)$i['product']->category_id===$categoryId)),0,$limit);}return response()->json(['method'=>'hybrid_content_affinity','items'=>$items]);}
 public function trackInteraction(Request $r, Product $product, JewelryRecommender $engine){$d=$r->validate(['event'=>'required|in:view,compare,wishlist,cart,purchase,review']);$engine->track($r,$product,$d['event']);return response()->json(['ok'=>true]);}
 public function recommendationPage(Request $r, JewelryRecommender $engine){$recommendations=$engine->recommend($r,null,12);return view('features.recommendations',compact('recommendations'));}
 public function verify(string $serial){$certificate=DB::table('certificates')->where('serial',$serial)->first();abort_unless($certificate,404);return view('features.certificate',compact('certificate'));}
}
